Definition callee (ps : SR.post_spec) (i j : nat) (c cj : CC.cutpoint) (scr : Z) (ng : nat) (wregs : list SGP.region) (news : list kentry) (a0x : option expr) : bool :=
  (CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
   && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI scr ng (nth i G.BLS []) (nth i FFS []) wregs news a0x c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
      | Some ci => Z.eqb (CH2.ci_csp ci) (-128) | None => false end)%bool.
Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      if Z.eqb pc RETPC then
        (CBA.exit_base_chk GT.NF RETPC c ps && CBA.regions_eqb (CC.cp_F c) CPF4 && Nat.ltb 81 (CC.cp_nx c)
         && match CHA.retire_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS []) with Some fle => expr_eqb fle FLE | None => false end
         && has cells (KWord (SA FLE 0) 1 (ELit 0))
         && ((Nat.eqb i 4 && has cells (KWord (SA PE 211) 1 (ELit 0)) && has cells (KWord (SA PE 208) 1 (ELit 15)))
             || (Nat.eqb i 9 && has cells (KWord (SA PE 211) 1 (ELit 1)) && has cells (KWord (SA PE 208) 1 (ELit 11)) && CBA.has_range cells (SEL 8) 1 1)
             || ((Nat.eqb i 5 || Nat.eqb i 8) && has cells (KWord (SA PE 211) 1 (ELit 1)) && has cells (KWord (SA PE 208) 1 (ELit 7)) && (CBA.has_range cells (SEL 7) 1 1 || CBA.has_range cells (SEL 4) 1 1))
             || (Nat.eqb i 7 && has cells (KWord (SA PE 211) 1 (ELit 1)) && has cells (KWord (SA PE 208) 1 (ELit 2)) && CBA.has_range cells (SEL 0) 1 1)))%bool
      else if Z.eqb pc DEADPC then
        (Nat.eqb i 3 && Nat.ltb 81 (CC.cp_nx c)
         && (CBA.has_range cells (EAlu Instr.ALU_ADD ROT (ELit (-9))) 0 246
             || (CBA.has_range cells (EAlu Instr.ALU_ADD ROT (ELit (-1))) 0 5 && CBA.has_range cells (SEL 4) 0 0)))%bool
      else
        match CH2.ret_of G.RETS i k with
        | Some j =>
            match nth_error G.CPS j with
            | Some cj =>
                (Z.eqb (SR.ps_pc ps) pc &&
                 if Z.eqb pc PC_SM then (Nat.eqb i 0 && Nat.eqb j 1 && CBA.regions_eqb (CC.cp_F c) CPF0
                                        && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                        && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 512 1 (nth i G.BLS []) (nth i FFS []) [] (List.filter (sm_ok ps i) (CC.cp_know cj)) None c ps cj
                                                   (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                           | Some ci => (Nat.eqb (CH2.ci_nx ci) 48 && Z.eqb (CH2.ci_csp ci) (-128))%bool | None => false end)
                 else if Z.eqb pc PC_VAL then (Nat.eqb i 1 && Nat.eqb j 2 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 53 (CC.cp_nx c)
                                              && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                              && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 128 0 (nth i G.BLS []) (nth i FFS []) [] NEWS_F None c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                                 | Some ci => (Z.eqb (CH2.ci_csp ci) (-128) && Nat.eqb (CH2.ci_nx ci) 65)%bool | None => false end
                                              && CL.ps_reg_is ps 10 SE && CL.ps_reg_is ps 11 LE && has cells (KWord (SA FE 120) 8 FLE) && CC.has_cell (CC.cp_know c) KZF)
                 else if Z.eqb pc PC_TCE then (Nat.eqb i 2 && Nat.eqb j 4 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 70 (CC.cp_nx c)
                                              && callee ps i j c cj 1120 0 TCE_W NEWS_T None
                                              && CL.ps_reg_is ps 10 PE && CL.ps_reg_is ps 11 CSX && CL.ps_reg_is ps 12 EE && has cells (KWord (SA FE 120) 8 FLE) && CBA.has_range cells CE 1 18446744073709551615)
                 else if Z.eqb pc PC_PAR then (Nat.eqb i 2 && Nat.eqb j 3 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 70 (CC.cp_nx c)
                                              && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                              && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 640 1 (nth i G.BLS []) (nth i FFS []) [] NEWS_P (Some XE) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                                 | Some ci => (Z.eqb (CH2.ci_csp ci) (-128) && Nat.eqb (CH2.ci_nx ci) 81)%bool | None => false end
                                              && CL.ps_reg_is ps 10 PE && has cells (KWord (SA FE 120) 8 FLE))
                 else if (Z.eqb pc PC_KEY || Z.eqb pc PC_VSTR) then      (* [comment removed for export] *)
                                             (Nat.eqb i 3 && (if Z.eqb pc PC_KEY then Nat.eqb j 6 else (Nat.eqb j 5 || Nat.eqb j 7 || Nat.eqb j 8)) && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 81 (CC.cp_nx c)
                                              && CHA.frames_eqb (nth j FFS []) (nth i FFS [])
                                              && callee ps i j c cj XKA.VIS 0 WENC NEWS_F (Some (ELit 1)) && has cells (KWord (SA FE 120) 8 FLE)
                                              && CL.ps_reg_is ps 10 VE && CL.ps_reg_is ps 11 SVA && (Z.eqb pc PC_KEY || CL.ps_reg_is ps 12 TAGE)
                                              && has cells (KWord (SA FE 48) 8 SE) && has cells (KWord (SA FE 56) 8 LE) && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 6)) 1 (ELit 0)) && has cells (KWord (SA (CHA.SRL3 FE) (SBz + 7)) 1 (ELit 0))
                                              && has cells (KZero (SA (CHA.SRL3 VE) SBz) (ELit 51)) && has cells (KZero (SA (CHA.SRL3 S2E) SBz) (ELit 3))
                                              && (Z.eqb pc PC_VSTR || CBA.has_range cells (SEL 8) 1 1))
                 else if Z.eqb pc PC_POP then (Nat.eqb i 6 && Nat.eqb j 9 && CBA.regions_eqb (CC.cp_F c) CPF1 && Nat.ltb 81 (CC.cp_nx c)
                                              && CHA.foot_chk GT.NF G.HDECL c (nth i G.BLS []) (nth i FFS [])
                                              && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 4256 1 (nth i G.BLS []) (nth i FFS []) POP_W NEWS_F (Some (EVar 114)) c ps cj (nth i G.BLS []) (nth i FFS []) (nth j G.BLS []) (nth j FFS []) with
                                                 | Some ci => (Z.eqb (CH2.ci_csp ci) (-128) && Nat.eqb (CH2.ci_nx ci) 114)%bool | None => false end
                                              && CL.ps_reg_is ps 10 PE && has cells (KWord (SA FE 120) 8 FLE))
                 else false)%bool
            | None => false end
        | None => false end
  end.
